// Shared column helpers (docs/architecture/data-model.md, SPEC-101 ET-2).
// Every mutable table uses `timestamps()` and declares its `set_updated_at` trigger in the custom
// migration of its own specification (checked by the generic convention test, CL-6).
import { timestamp, uuid } from 'drizzle-orm/pg-core';

/** UUID primary key generated by Postgres (`gen_random_uuid()`), never by the application clock. */
export const id = () => uuid('id').primaryKey().defaultRandom();

/** Creation instant produced by Postgres `now()` (ADR-0047: no application `new Date()`). */
export const createdAt = () =>
  timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();

/** Last mutation instant, maintained by `public.set_updated_at()` (ET-4). */
export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();

export const timestamps = () => ({ createdAt: createdAt(), updatedAt: updatedAt() });
